<?php require dirname(__DIR__).'/includes/bootstrap.php';$u=require_permission('QUAN_LY_KHO');$scope=$u['quyen']==='ADMIN'?'1=1':'ma_showroom IN(SELECT ma_showroom FROM pham_vi_showroom WHERE tai_khoan_id='.(int)$u['id'].')';$rows=db_all("SELECT so_khung_vin,ma_cau_hinh,ma_showroom,so_may,mau_sac,nam_san_xuat,gia_von,ngay_nhap_dau FROM xe WHERE $scope ORDER BY so_khung_vin");$headers=['so_khung_vin','ma_cau_hinh','ma_showroom','so_may','mau_sac','nam_san_xuat','gia_von','ngay_nhap_dau'];$safe=fn($s)=>preg_match('/^[=+@-]/',(string)$s)?"'".$s:$s;
if(get('format')==='xlsx'){$book=new PhpOffice\PhpSpreadsheet\Spreadsheet();$sheet=$book->getActiveSheet();$sheet->fromArray($headers,null,'A1');$i=2;foreach($rows as$r){$col=1;foreach($r as$v){$sheet->setCellValueExplicit(PhpOffice\PhpSpreadsheet\Cell\Coordinate::stringFromColumnIndex($col++).$i,(string)$v,PhpOffice\PhpSpreadsheet\Cell\DataType::TYPE_STRING);}$i++;}header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="kho-xe.xlsx"');(new PhpOffice\PhpSpreadsheet\Writer\Xlsx($book))->save('php://output');exit;}
if(get('format')==='csv'){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="kho-xe.csv"');$f=fopen('php://output','w');fwrite($f,"\xEF\xBB\xBF");fputcsv($f,$headers,',','"','');foreach($rows as$r)fputcsv($f,array_map($safe,$r),',','"','');fclose($f);exit;}page_start('Xuất dữ liệu kho');echo '<div class="actions"><a class="button" href="'.e(url('admin/xuat_kho.php?format=csv')).'">Tải CSV</a><a class="button ghost" href="'.e(url('admin/xuat_kho.php?format=xlsx')).'">Tải Excel XLSX</a></div>';notice('Xuất tệp dữ liệu không thay đổi trạng thái xe trong kho.');page_end();
